<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,clp,errorText} from '../api';import {useAuth} from '../stores/auth';import PageHeading from '../components/PageHeading.vue';import Modal from '../components/Modal.vue';import {Plus,Search,ArrowUpRight} from 'lucide-vue-next';
const auth=useAuth(),companies=ref<any[]>([]),team=ref<any[]>([]),error=ref(''),busy=ref(false),loading=ref(true),show=ref(false),search=ref(''),page=ref(1),last=ref(1),archived=ref(false);const form=ref({name:'',trade_name:'',rut:'',business:'',address:'',contact_name:'',contact_email:'',contact_phone:'',service:'Contabilidad mensual',monthly_fee:150000,responsible_id:null as number|null});
async function load(p=1){page.value=p;loading.value=true;error.value='';try{const d=(await api.get('/companies',{params:{search:search.value,page:p,archived:archived.value?1:0}})).data;companies.value=d.data;last.value=d.last_page;}catch(e){error.value=errorText(e);}finally{loading.value=false;}}
async function create(){busy.value=true;error.value='';try{await api.post('/companies',form.value);show.value=false;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}onMounted(async()=>{await load();if(auth.admin)try{team.value=(await api.get('/team')).data;}catch(e){error.value=errorText(e);}});
</script>
<template><PageHeading title="Empresas" subtitle="Toda tu cartera, con el contexto que necesitas."><button v-if="auth.admin" class="button primary" @click="show=true"><Plus :size="16"/>Nueva empresa</button></PageHeading><div class="toolbar"><form @submit.prevent="load(1)" class="search-form"><Search :size="17"/><input v-model="search" type="search" aria-label="Buscar empresa" placeholder="Nombre o RUT"><button class="button">Buscar</button></form><label class="checkbox"><input type="checkbox" v-model="archived" @change="load(1)">Incluir archivadas</label></div><div v-if="error" class="error" role="alert">{{error}}</div><div v-if="loading" class="empty">Cargando empresas…</div><section v-else class="panel"><div class="table-wrap"><table><thead><tr><th>Empresa</th><th>Servicio</th><th>Responsable</th><th v-if="auth.admin">Honorario mensual</th><th></th></tr></thead><tbody><tr v-for="c in companies" :key="c.id"><td><RouterLink :to="`/companies/${c.id}`" class="entity-name">{{c.trade_name||c.name}}</RouterLink><small>{{c.rut}} <span v-if="c.archived_at">· Archivada</span></small></td><td>{{c.service}}</td><td>{{c.responsible?.name||'Sin asignar'}}</td><td v-if="auth.admin">{{clp(c.monthly_fee)}}</td><td><RouterLink :to="`/companies/${c.id}`" class="row-action" aria-label="Abrir ficha de empresa"><ArrowUpRight :size="17"/></RouterLink></td></tr></tbody></table><div v-if="!companies.length" class="empty">No hay empresas que coincidan. {{auth.admin?'Crea la primera o cambia la búsqueda.':''}}</div></div><div class="pagination"><button class="button" :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{last}}</span><button class="button" :disabled="page>=last" @click="load(page+1)">Siguiente</button></div></section><Modal v-if="show" title="Nueva empresa" @close="show=false"><form @submit.prevent="create" class="form-grid"><label>Razón social<input v-model="form.name" required maxlength="180"></label><label>Nombre de fantasía<input v-model="form.trade_name"></label><label>RUT<input v-model="form.rut" required placeholder="76.000.000-0"></label><label>Giro<input v-model="form.business"></label><label>Dirección<input v-model="form.address"></label><label>Contacto<input v-model="form.contact_name"></label><label>Correo<input v-model="form.contact_email" type="email"></label><label>Teléfono<input v-model="form.contact_phone" type="tel"></label><label>Servicio<input v-model="form.service" required></label><label>Honorario mensual CLP<input v-model.number="form.monthly_fee" type="number" min="0" required></label><label>Responsable<select v-model="form.responsible_id"><option :value="null">Sin asignar</option><option v-for="u in team" :key="u.id" :value="u.id">{{u.name}}</option></select></label><p v-if="error" class="error span-two" role="alert">{{error}}</p><div class="form-footer"><button type="button" class="button" @click="show=false">Cancelar</button><button class="button primary" :disabled="busy">{{busy?'Guardando…':'Crear empresa'}}</button></div></form></Modal></template>
